 Panel host;Label pageTitle,pageCaption;ComboBox family;TextBox directory;int activePage;
 Font F(float size,bool bold=false,string name="Microsoft YaHei UI"){string key=name+size+bold;Font font;if(!fonts.TryGetValue(key,out font)){font=FontTools.Create(name,size,bold?FontStyle.Bold:FontStyle.Regular);fonts[key]=font;}return font;}
 Label TextLabel(string text,float size=10,bool bold=false){return new Label{Text=text,AutoSize=true,Font=F(size,bold),ForeColor=ink,Margin=new Padding(0,0,0,6)};}
