  SuspendLayout();Value=current.Copy();save=onSave;Text="设置 · oii背词";StartPosition=FormStartPosition.CenterParent;AutoScaleDimensions=new SizeF(96,96);AutoScaleMode=AutoScaleMode.Dpi;Font=F(10);BackColor=Color.FromArgb(246,248,246);ClientSize=new Size(960,660);MinimumSize=new Size(880,620);
