  var heading=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(0,0,0,20)};pageTitle=TextLabel("",22,true);pageCaption=TextLabel("",9);pageCaption.ForeColor=muted;heading.Controls.Add(pageTitle);heading.Controls.Add(pageCaption);main.Controls.Add(heading,0,0);
