  var footer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Padding=new Padding(0,14,0,0),Margin=Padding.Empty};footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));footer.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));var reset=new LinkLabel{Text="恢复默认外观",AutoSize=true,Font=F(9),LinkColor=muted,ActiveLinkColor=green,Anchor=AnchorStyles.Left,Margin=Padding.Empty};reset.LinkClicked+=delegate{string dir=directory.Text;Value=new AppearanceSettings();Value.DataDirectory=dir;BuildPages();SelectPage(activePage);};footer.Controls.Add(reset,0,0);var actions=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill,WrapContents=false,Margin=Padding.Empty};var cancel=Button("取消");cancel.Width=80;cancel.Click+=delegate{Close();};actions.Controls.Add(cancel);var apply=Button("保存并应用",true);apply.Width=130;apply.Click+=delegate{try{Value.Family=family.Text;Value.DataDirectory=System.IO.Path.GetFullPath(directory.Text.Trim());AppearanceStore.Validate(Value);save(Value);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"设置未保存");}};actions.Controls.Add(apply);footer.Controls.Add(actions,1,0);main.Controls.Add(footer,0,2);CancelButton=cancel;SelectPage(0);ResumeLayout(true);
