 protected override void OnShown(EventArgs e){base.OnShown(e);LoadFontChoices();}
 protected override void Dispose(bool disposing){base.Dispose(disposing);if(disposing){foreach(var f in fonts.Values)f.Dispose();fonts.Clear();}}
 void LoadFontChoices(){var target=family;FontCatalog.Names.ContinueWith(task=>{if(task.IsFaulted||IsDisposed||!IsHandleCreated)return;try{BeginInvoke((Action)delegate{if(IsDisposed||target.IsDisposed||target!=family)return;string chosen=target.Text;target.BeginUpdate();try{target.Items.Clear();target.Items.AddRange(task.Result.Cast<object>().ToArray());if(!target.Items.Contains(chosen))target.Items.Add(chosen);target.SelectedItem=chosen;}finally{target.EndUpdate();}});}catch(InvalidOperationException){}});}
 void SelectPage(int index){activePage=index;string[] titles={"字体排版","主题颜色","布局显示","缓存存档"};string[] captions={"让每个单词都清晰易读。","用喜欢的颜色，营造舒适的学习空间。","按你的习惯安排词卡与信息。","管理浏览进度的保存位置。"};pageTitle.Text=titles[index];pageCaption.Text=captions[index];for(int i=0;i<pages.Count;i++){pages[i].Visible=i==index;navigation[i].BackColor=i==index?Color.White:Color.FromArgb(236,242,237);navigation[i].ForeColor=i==index?green:muted;navigation[i].FlatAppearance.BorderColor=i==index?line:Color.FromArgb(236,242,237);}pages[index].BringToFront();}
 TableLayoutPanel Card(string title,string subtitle=""){var card=new RoundedCard{Outline=line,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,Dock=DockStyle.Top,ColumnCount=1,RowCount=0,BackColor=Color.White,Padding=new Padding(18),Margin=new Padding(0,0,14,16)};Add(card,TextLabel(title,12,true));if(subtitle.Length>0){var hint=TextLabel(subtitle,9);hint.ForeColor=muted;hint.Margin=new Padding(0,0,0,16);Add(card,hint);}return card;}
 void Add(TableLayoutPanel panel,Control c){int row=panel.RowCount++;panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));c.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;panel.Controls.Add(c,0,row);}
 TableLayoutPanel Page(){var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Margin=Padding.Empty};host.Controls.Add(scroll);pages.Add(scroll);var grid=new TableLayoutPanel{AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,Dock=DockStyle.Top,ColumnCount=2,RowCount=1,Margin=Padding.Empty,Padding=new Padding(0,0,0,12)};grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,62));grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,38));grid.RowStyles.Add(new RowStyle(SizeType.AutoSize));scroll.Controls.Add(grid);return grid;}
 void Row(TableLayoutPanel card,string label,Control input){var row=new TableLayoutPanel{AutoSize=true,ColumnCount=2,RowCount=1,Dock=DockStyle.Top,Margin=new Padding(0,5,0,5),Padding=new Padding(0,5,0,5)};row.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));row.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,label=="显示字体"?190:116));var text=TextLabel(label);text.Anchor=AnchorStyles.Left;text.Margin=Padding.Empty;row.Controls.Add(text,0,0);input.Anchor=AnchorStyles.Left|AnchorStyles.Right;input.Margin=Padding.Empty;row.Controls.Add(input,1,0);Add(card,row);}
 ComboBox Combo(){return new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(244,247,244),ForeColor=ink,Font=F(10),MaxDropDownItems=12,IntegralHeight=true};}
 void Number(TableLayoutPanel card,string label,int value,int min,int max,Action<int> change){var input=Combo();for(int i=min;i<=max;i++)input.Items.Add(i);input.SelectedItem=value;input.SelectedIndexChanged+=delegate{change((int)input.SelectedItem);Preview();};Row(card,label,input);}
 void Toggle(TableLayoutPanel card,string label,bool value,Action<bool> change){var input=new RoundedCheckBox{Appearance=Appearance.Button,FlatStyle=FlatStyle.Flat,Checked=value,Text=value?"已开启":"已关闭",TextAlign=ContentAlignment.MiddleCenter,Height=32,Font=F(9),BackColor=value?Color.FromArgb(230,241,233):Color.FromArgb(244,246,244),ForeColor=value?green:muted};input.FlatAppearance.BorderSize=0;input.CheckedChanged+=delegate{input.Text=input.Checked?"已开启":"已关闭";input.BackColor=input.Checked?Color.FromArgb(230,241,233):Color.FromArgb(244,246,244);input.ForeColor=input.Checked?green:muted;change(input.Checked);Preview();};Row(card,label,input);}
 void Colour(TableLayoutPanel card,string label,Func<Color> get,Action<Color> change){var b=Button("");b.Height=32;b.Font=F(9);((RoundedButton)b).AfterPaint+=delegate(object sender,PaintEventArgs e){int size=(int)(16*e.Graphics.DpiX/96f);using(var brush=new SolidBrush(get()))e.Graphics.FillRectangle(brush,8,(b.Height-size)/2,size,size);};b.TextAlign=ContentAlignment.MiddleRight;b.Padding=new Padding(0,0,6,0);swatches[b]=get;b.Click+=delegate{using(var d=new ColorDialog{Color=get(),FullOpen=true})if(d.ShowDialog(this)==DialogResult.OK){change(d.Color);Preview();}};Row(card,label,b);}
 TableLayoutPanel PreviewPanel(){var card=Card("即时预览","预览你的词卡效果");card.Margin=new Padding(0,0,0,16);var word=TextLabel("evolve",25,true);word.Margin=new Padding(0,16,0,18);Add(card,word);var meaning=TextLabel("v.  ★ 进化；发展",17);meaning.Margin=new Padding(0,0,0,22);Add(card,meaning);var example=TextLabel("Ideas evolve over time.",10);example.Margin=new Padding(0,0,0,8);Add(card,example);var translation=TextLabel("想法会随着时间演变。",10);Add(card,translation);card.SizeChanged+=delegate{int width=Math.Max(80,card.ClientSize.Width-card.Padding.Horizontal);foreach(var label in new[]{word,meaning,example,translation})if(!label.IsDisposed)label.MaximumSize=new Size(width,0);};previewUpdates.Add(delegate{card.BackColor=Value.Card;word.Font=F(Value.WordSize,true,Value.Family);meaning.Font=F(Value.MeaningSize,true,Value.Family);example.Font=F(Value.ExampleSize,false,Value.Family);translation.Font=F(Value.TranslationSize,false,Value.Family);word.ForeColor=Value.Text;meaning.ForeColor=Value.Accent;example.ForeColor=translation.ForeColor=Value.Text;example.Visible=translation.Visible=Value.ShowExamples;});return card;}
 void Preview(){foreach(var pair in swatches){var c=pair.Value();pair.Key.Text="#"+c.R.ToString("X2")+c.G.ToString("X2")+c.B.ToString("X2");pair.Key.Invalidate();}foreach(var update in previewUpdates)update();}
