  var typography=Page();var type=Card("字体与字号","不同内容可以分别调整");family=Combo();family.Items.AddRange(new[]{Value.Family,"Microsoft YaHei UI","Microsoft YaHei","Segoe UI","Arial","SimSun","KaiTi"}.Distinct().Cast<object>().ToArray());family.SelectedItem=Value.Family;family.SelectedIndexChanged+=delegate{Value.Family=family.Text;Preview();};Row(type,"显示字体",family);Number(type,"英文单词",Value.WordSize,18,42,v=>Value.WordSize=v);Number(type,"中文释义",Value.MeaningSize,12,28,v=>Value.MeaningSize=v);Number(type,"英文例句",Value.ExampleSize,10,22,v=>Value.ExampleSize=v);Number(type,"中文译文",Value.TranslationSize,10,24,v=>Value.TranslationSize=v);Number(type,"左侧列表",Value.ListSize,10,18,v=>Value.ListSize=v);typography.Controls.Add(type,0,0);typography.Controls.Add(PreviewPanel(),1,0);
  var theme=Page();var colors=Card("主题与颜色","从配色开始，也可以逐项微调");var presets=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top,WrapContents=true,Margin=new Padding(0,0,0,12)};string[] names={"森绿","雾蓝","暖白"};for(int i=0;i<3;i++){int index=i;var b=Button(names[i]);b.Width=78;b.Height=34;b.Margin=new Padding(0,0,8,8);b.Click+=delegate{Value.Background=index==1?Color.FromArgb(242,246,250):index==2?Color.FromArgb(249,246,239):Color.FromArgb(245,248,243);Value.Card=index==2?Color.FromArgb(255,253,246):Color.White;Value.Text=Color.FromArgb(23,36,28);Value.Accent=index==1?Color.FromArgb(48,95,143):index==2?Color.FromArgb(145,105,55):Color.FromArgb(33,113,69);Preview();};presets.Controls.Add(b);}Add(colors,presets);Colour(colors,"文字",()=>Value.Text,c=>Value.Text=c);Colour(colors,"星标与强调",()=>Value.Accent,c=>Value.Accent=c);Colour(colors,"窗口背景",()=>Value.Background,c=>Value.Background=c);Colour(colors,"词卡与列表",()=>Value.Card,c=>Value.Card=c);theme.Controls.Add(colors,0,0);var tips=Card("配色建议","让阅读轻松一点");var note=TextLabel("浅色背景搭配深色文字，\n长时间复习更容易看清。\n\n星标建议使用更醒目的颜色。",9);note.ForeColor=muted;Add(tips,note);tips.Dispose();theme.Controls.Add(PreviewPanel(),1,0);
  var layout=Page();var spacing=Card("布局与显示","保留你最常用的信息");Number(spacing,"侧栏宽度",Value.Sidebar,260,380,v=>Value.Sidebar=v);Number(spacing,"释义左侧留白",Value.Inset,0,40,v=>Value.Inset=v);Number(spacing,"翻词按钮高度",Value.ButtonHeight,40,64,v=>Value.ButtonHeight=v);Toggle(spacing,"音标",Value.ShowPhonetic,v=>Value.ShowPhonetic=v);Toggle(spacing,"例句与译文",Value.ShowExamples,v=>Value.ShowExamples=v);Toggle(spacing,"出现次数",Value.ShowCounts,v=>Value.ShowCounts=v);layout.Controls.Add(spacing,0,0);var shortcuts=Card("快捷键");var keys=TextLabel("A / ↑   上一词\n\nD / ↓   下一词\n\n空格   显隐中文\n\n左 Alt   回到本分类标记\n\n. / F   加入待复习",10);keys.ForeColor=muted;Add(shortcuts,keys);layout.Controls.Add(shortcuts,1,0);
  var storage=Page();var location=Card("保存位置","浏览进度会自动保存到这里");directory=new TextBox{Text=Value.DataDirectory,BorderStyle=BorderStyle.FixedSingle,Font=F(10),Dock=DockStyle.Top,Margin=new Padding(0,8,0,14)};Add(location,directory);var browse=Button("更换文件夹…");browse.Width=140;browse.Anchor=AnchorStyles.Left;browse.Margin=new Padding(0,0,0,8);browse.Click+=delegate{using(var dialog=new FolderBrowserDialog{Description="选择缓存与浏览存档保存位置",SelectedPath=directory.Text})if(dialog.ShowDialog(this)==DialogResult.OK)directory.Text=dialog.SelectedPath;};Add(location,browse);storage.Controls.Add(location,0,0);var safety=Card("进度随你走");var info=TextLabel("更换位置时会复制当前进度，\n并保留原来的存档。\n\n词库内置，可离线使用。",9);info.ForeColor=muted;Add(safety,info);storage.Controls.Add(safety,1,0);
  Preview();host.ResumeLayout(true);if(IsHandleCreated)LoadFontChoices();
